/**
 * npm run gen — scans src/modules/<module>/index.ts and writes src/generated/registry.ts,
 * which imports each module's default export. Runs before dev, build, test, typecheck
 * and db:seed. The generated file is gitignored, so modules never conflict over it.
 */
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = process.cwd();
const modulesDir = join(root, "src/modules");
const outDir = join(root, "src/generated");
const outFile = join(outDir, "registry.ts");

export function findModules(dir = modulesDir): string[] {
  if (!existsSync(dir)) return [];
  return readdirSync(dir, { withFileTypes: true })
    .filter((d) => d.isDirectory() && existsSync(join(dir, d.name, "index.ts")))
    .map((d) => d.name)
    .sort();
}

export function renderRegistry(names: string[]): string {
  const ident = (name: string) => `m_${name.replace(/[^a-zA-Z0-9]/g, "_")}`;
  return [
    "// Generated by `npm run gen` (scripts/gen-registry.ts) from src/modules/*/index.ts.",
    "// Do not edit and do not commit: it is rebuilt before dev, build, test and typecheck.",
    'import type { ZinnyModule } from "@/contracts/module";',
    ...names.map((n) => `import ${ident(n)} from "@/modules/${n}";`),
    "",
    "/** Every module, keyed by folder name. */",
    "export const generatedModules: Readonly<Record<string, ZinnyModule>> = {",
    ...names.map((n) => `  ${JSON.stringify(n)}: ${ident(n)},`),
    "};",
    "",
  ].join("\n");
}

function main() {
  const names = findModules();
  for (const n of names) {
    const src = readFileSync(join(modulesDir, n, "index.ts"), "utf8");
    if (!/export\s+default\s/.test(src)) {
      console.error(`src/modules/${n}/index.ts must default-export its ZinnyModule (export default …).`);
      process.exit(1);
    }
  }
  mkdirSync(outDir, { recursive: true });
  const next = renderRegistry(names);
  const current = existsSync(outFile) ? readFileSync(outFile, "utf8") : "";
  if (current !== next) writeFileSync(outFile, next);
  console.log(`Registry: ${names.length} module${names.length === 1 ? "" : "s"} (${names.join(", ") || "none"}).`);
}

if (process.argv[1]?.endsWith("gen-registry.ts")) main();
